import json
import numpy as np
from itertools import combinations

results = []
for d in DATA:
    results.append({'DEPTH': d['config']['DEPTH'], 'MATRIX_LR': d['config']['MATRIX_LR'], 'WEIGHT_DECAY': d['config']['WEIGHT_DECAY'], 'outcome': d['outcome']})

# Main effects
analysis = {'main_effects': {}, 'best_config': None, 'worst_config': None}
for factor in ['DEPTH', 'MATRIX_LR', 'WEIGHT_DECAY']:
    levels = {}
    for r in results:
        lv = r[factor]
        levels.setdefault(lv, []).append(r['outcome'])
    analysis['main_effects'][factor] = {k: round(np.mean(v), 4) for k, v in sorted(levels.items())}

best = max(results, key=lambda x: x['outcome'])
worst = min(results, key=lambda x: x['outcome'])
analysis['best_config'] = {k: v for k, v in best.items()}
analysis['worst_config'] = {k: v for k, v in worst.items()}
analysis['outcome_range'] = round(best['outcome'] - worst['outcome'], 4)

print(json.dumps(analysis, indent=2))

